        return None

    # Validate input
    if not isinstance(commit_hash, str):
        status = "error"
        rl = _log_call("error", "VALIDATION_ERROR")
        if rl: return rl
        return _err("VALIDATION_ERROR", "commit_hash must be a string")
    commit_hash = commit_hash.strip()
    if not commit_hash:
        status = "error"
        rl = _log_call("error", "VALIDATION_ERROR")
        if rl: return rl
        return _err("VALIDATION_ERROR", "commit_hash is required")
    if not re.fullmatch(r"[0-9a-fA-F]{7,40}", commit_hash):
        status = "error"
        rl = _log_call("error", "VALIDATION_ERROR")
        if rl: return rl
        return _err("VALIDATION_ERROR", "commit_hash is not a valid-looking SHA hash")

    commits_payload = _load("commits.json")
    commits = _ensure_list(commits_payload)
    if not commits:
        status = "error"
        rl = _log_call("error", "UNAUTHORIZED")
        if rl: return rl
        return _err("UNAUTHORIZED", "Repository history is not accessible")

    found = None
    for c in commits:
        if isinstance(c, dict) and c.get("hash") == commit_hash:
            found = c
            break

    if not found:
        status = "error"
        rl = _log_call("error", "NOT_FOUND")
        if rl: return rl
        return _err("NOT_FOUND", "Commit not found", commit_hash=commit_hash)

    rl = _log_call(status)
    if rl: return rl
    return {"commit": found}

