def list_tags(name_filter=None, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0545000" if __import__("os").path.isdir("./environment_mix/0545000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_tags"

    def _normalize_rows(payload):
        # Accept either a plain list of rows or {"rows":[...]} shape
        if isinstance(payload, list):
            return payload
        if isinstance(payload, dict) and isinstance(payload.get("rows"), list):
            return payload["rows"]
        # If store has unexpected shape, treat as empty (no error for reads)
        return []

    def _read_usage():
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            usage = {}
        if not isinstance(usage.get("requests"), list):
            usage["requests"] = []
        if not isinstance(usage.get("counters"), dict):
            usage["counters"] = {}
        if not isinstance(usage.get("rate_limits"), dict):
            usage["rate_limits"] = {}
        return usage

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", ""))
        except Exception:
            return None

    def _enforce_and_log(status_value, error_code=None):
        usage = _read_usage()
        now = datetime.datetime.utcnow()

        # Rate limit: 120 requests per 60 seconds (global), enforced against existing logs
        window_s = 60
        limit_rl = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in reversed(usage["requests"]):
            rt = _parse_ts(r.get("timestamp"))
            if rt is None:
                continue
            if rt < cutoff:
                break
            recent += 1

        if recent >= limit_rl and status_value != "rate_limited":
            # Log the refused call too
            status_value = "rate_limited"
            error_code = "RATE_LIMIT"

        usage["counters"]["total_requests"] = int(usage["counters"].get("total_requests", 0) or 0) + 1
        usage["counters"][f"requests_{endpoint}"] = int(usage["counters"].get(f"requests_{endpoint}", 0) or 0) + 1

        usage["requests"].append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(usage['requests'])+1}",
            "endpoint": endpoint,
            "credential": None,
            "status": status_value,
            "error_code": error_code,
            "timestamp": now.replace(microsecond=0).isoformat() + "Z",
            "latency_ms": int((time.time() - _t0) * 1000),
        })
        _save("usage.json", usage)

        if status_value == "rate_limited":
            return _err("RATE_LIMIT", "Too many requests, please retry later.", window_seconds=window_s, limit=limit_rl)
        return None

    # Validate inputs
    if name_filter is not None and not isinstance(name_filter, str):
        err = _enforce_and_log("error", "VALIDATION_ERROR")
        return err or _err("VALIDATION_ERROR", "name_filter must be a string", name_filter=name_filter)

    if limit is not None:
        if not isinstance(limit, int):
            err = _enforce_and_log("error", "VALIDATION_ERROR")
            return err or _err("VALIDATION_ERROR", "limit must be an integer", limit=limit)
        if limit <= 0:
            err = _enforce_and_log("error", "VALIDATION_ERROR")
            return err or _err("VALIDATION_ERROR", "limit must be greater than 0", limit=limit)

    # Enforce rate limit before doing the work (based on prior requests)
    rl_err = _enforce_and_log("ok")  # will also log; if rate-limited, returns error
    if isinstance(rl_err, dict) and rl_err.get("error", {}).get("code") == "RATE_LIMIT":
        return rl_err

    # Perform read
    tags_payload = _load("tags.json")
    rows = _normalize_rows(tags_payload)

    # Filter: match on tag name containing substring
    if name_filter:
        nf = name_filter.lower()
        rows = [r for r in rows if isinstance(r, dict) and isinstance(r.get("tag"), str) and nf in r["tag"].lower()]
    else:
        rows = [r for r in rows if isinstance(r, dict)]

    total = len(rows)

    # Apply limit
    if limit is not None:
        rows = rows[:limit]

    # Return envelope with metadata
    has_more = (limit is not None and total > len(rows))
    return {
        "object": "list",
        "data": rows,
        "total": total,
        "has_more": bool(has_more),
        "next_cursor": None
    }

