def get_repo_structure(path_filter=None):
    import json, os
    path = os.path.join(_DB, 'repo_structure.json')
    try:
        with open(path, 'r', encoding='utf-8') as f:
            structure = json.load(f)
    except FileNotFoundError:
        return {}
    if not path_filter:
        return structure
    files = structure.get('files', [])
    filtered_files = [f for f in files if path_filter in f.get('path', '')]
    new_structure = dict(structure)
    new_structure['files'] = filtered_files
    return new_structure

