def find_file(file_path):
    import json, os
    path = os.path.join(_DB, 'repo_structure.json')
    try:
        with open(path, 'r', encoding='utf-8') as f:
            structure = json.load(f)
    except FileNotFoundError:
        return None
    for f in structure.get('files', []):
        if f.get('path') == file_path:
            return f
    return None
